css_to_add = """
        .feature-icon-svg {
            display: block;
            margin-bottom: 1.5rem;
            color: inherit;
        }
        /* Fallback colors if not handled by parent */
        .feature-card .feature-icon-svg { color: var(--lime, var(--primary-color, inherit)); }
"""

directory = r'c:\Users\52319400\Downloads\portf\templates\projetos'
for root, dirs, files in os.walk(directory):
    for file in files:
        if file.endswith('.html'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()
                
            modified = False
            for emoji_char, svg in replacements.items():
                if emoji_char in content:
                    content = content.replace(emoji_char, svg)
                    modified = True
                    
            if modified:
                # Add the CSS snippet right before </style> if not there
                if "feature-icon-svg" not in content and "</style>" in content:
                    content = content.replace("</style>", css_to_add + "\n    </style>")
                    
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(content)
                print(f"Removed emojis from {file}")
